/* T3 Chat Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="t3-chat-light"] {
  --background: rgb(252, 246, 252);
  --foreground: rgb(82, 24, 86);
  --card: rgb(252, 246, 252);
  --card-foreground: rgb(82, 24, 86);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(82, 24, 86);
  --primary: rgb(167, 67, 112);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(242, 196, 231);
  --secondary-foreground: rgb(117, 52, 121);
  --muted: rgb(248, 228, 244);
  --muted-foreground: rgb(129, 70, 134);
  --accent: rgb(242, 196, 231);
  --accent-foreground: rgb(117, 52, 121);
  --destructive: rgb(171, 64, 69);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(239, 191, 235);
  --input: rgb(232, 191, 220);
  --ring: rgb(219, 36, 118);
  --chart-1: rgb(217, 32, 161);
  --chart-2: rgb(107, 7, 186);
  --chart-3: rgb(42, 71, 83);
  --chart-4: rgb(231, 195, 101);
  --chart-5: rgb(244, 162, 93);
  --radius: 0.5rem;
  --sidebar: rgb(245, 229, 248);
  --sidebar-foreground: rgb(170, 20, 103);
  --sidebar-primary: rgb(70, 70, 88);
  --sidebar-primary-foreground: rgb(250, 243, 247);
  --sidebar-accent: rgb(248, 248, 248);
  --sidebar-accent-foreground: rgb(70, 70, 88);
  --sidebar-border: rgb(235, 235, 235);
  --sidebar-ring: rgb(219, 36, 118);
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
    "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    "Courier New", monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

