  --popover-foreground: rgb(247, 239, 244);
  --primary: rgb(163, 0, 76);
  --primary-foreground: rgb(239, 194, 217);
  --secondary: rgb(53, 44, 60);
  --secondary-foreground: rgb(213, 199, 226);
  --muted: rgb(39, 33, 43);
  --muted-foreground: rgb(193, 180, 207);
  --accent: rgb(69, 54, 81);
  --accent-foreground: rgb(247, 239, 244);
  --destructive: rgb(48, 18, 22);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(61, 49, 56);
  --input: rgb(62, 52, 60);
  --ring: rgb(219, 36, 118);
  --chart-1: rgb(167, 67, 112);
  --chart-2: rgb(146, 76, 201);
  --chart-3: rgb(231, 139, 47);
  --chart-4: rgb(175, 88, 218);
  --chart-5: rgb(226, 53, 111);
  --radius: 0.5rem;
  --sidebar: rgb(25, 17, 24);
